            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    /**
     * Loads and validates the configuration. Every problem found is reported in a single {@link ConfigException}, one
     * per line, so the deployer can fix them all at once. Nothing is silently replaced by a default: only keys that
     * are absent get one.
     */
    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();

        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add("unknown key '" + key + "'");
            }
        }
        URI upstream = uri(properties, "upstream.url", problems);
        String apiToken = required(properties, "api.token", problems);
        int workerThreads = intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = duration(properties, "request.timeout", problems);
        boolean metricsEnabled = bool(properties, "metrics.enabled", problems);

        if (!problems.isEmpty()) {
            throw new ConfigException("invalid configuration in " + file + ":\\n  - " + String.join("\\n  - ", problems));
        }
        return new ServiceConfig(
                upstream, apiToken, workerThreads, queueCapacity, retryAttempts, requestTimeout, metricsEnabled);
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("cannot read configuration file " + file + ": " + e);
        }
        return properties;
    }

    private static String required(Properties properties, String key, List<String> problems) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private static URI uri(Properties properties, String key, List<String> problems) {
        String raw = required(properties, key, problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            String scheme = uri.getScheme();
            if (scheme == null || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))
                    || uri.getHost() == null) {
                problems.add(key + " must be an http or https URL with a host, but was '" + raw + "'");
                return null;
            }
            return uri;
        } catch (URISyntaxException e) {
            problems.add(key + " is not a valid URL: '" + raw + "'");
            return null;
        }
    }

    private static int intValue(Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw.trim());
            if (value < minimum) {
                problems.add(key + " must be at least " + minimum + ", but was '" + raw.trim() + "'");
            }
            return value;
        } catch (NumberFormatException e) {
            problems.add(key + " must be a whole number, but was '" + raw.trim() + "'");
            return defaultValue;
        }
    }

    private static boolean bool(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (value.equals("true") || value.equals("false")) {
            return Boolean.parseBoolean(value);
        }
        problems.add(key + " must be 'true' or 'false', but was '" + value + "'");
        return false;
    }

    private static Duration duration(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (matcher.matches()) {
            try {
                long amount = Long.parseLong(matcher.group(1));
                Duration result = switch (matcher.group(2)) {
                    case "ms" -> Duration.ofMillis(amount);
                    case "s" -> Duration.ofSeconds(amount);
                    default -> Duration.ofMinutes(amount);
                };
                if (!result.isZero()) {
                    return result;
                }
            } catch (ArithmeticException | NumberFormatException e) {
                // reported below
            }
        }
        problems.add(key + " must be a positive whole number plus ms, s or m (e.g. 30s), but was '" + raw.trim() + "'");
        return DEFAULT_REQUEST_TIMEOUT;
    }
}
